import React from 'react';
import { Spin } from 'antd';

const LoadingOverlay = ({ loading, }) => {
  if (!loading) return null;

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100%',
      height: '100%',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      zIndex: 9999
    }}>
      <Spin size="large" />
    </div>
  );
};

export default LoadingOverlay;